const cliConsoleHttpUrl = await Promise.race([
  new Promise<string>((resolve) => {
    cliConsoleHttp.stdout.on("data", () => {
      const match = cliConsoleHttpStdout.match(/"url": "(http:\/\/127\.0\.0\.1:\d+)"/u);
      if (match?.[1]) resolve(match[1]);
    });
  }),
  new Promise<never>((_, reject) => {
    cliConsoleHttp.once("exit", (code, signal) => {
      reject(new Error(`gmos http serve --console exited early: code=${code} signal=${signal} stderr=${cliConsoleHttpStderr}`));
    });
  }),
  new Promise<never>((_, reject) =>
    setTimeout(() => reject(new Error(`gmos http serve --console did not print url: ${cliConsoleHttpStderr}`)), 5000),
  ),
]);
try {
  assert.match(cliConsoleHttpStdout, /"console": true/);
  const cliConsoleShell = await fetch(`${cliConsoleHttpUrl}/console/`);
  assert.equal(cliConsoleShell.status, 200);
  assert.match(await cliConsoleShell.text(), /Memory Console/);
  const cliConsoleDataRoute = await httpJson(`${cliConsoleHttpUrl}/runtime-info`);
  assert.equal(cliConsoleDataRoute.status, 401);
} finally {
  cliConsoleHttp.kill("SIGTERM");
  await Promise.race([
    new Promise((resolve) => cliConsoleHttp.once("exit", resolve)),
    new Promise((resolve) => setTimeout(resolve, 5000)),
  ]);
}

const cliAutopilotHttp = spawn(
  process.execPath,
  [
    "--import",
    "tsx",
    "src/cli/gmos.ts",
    "http",
    "serve",
    "--db",
    path.join(tmp, "cli-autopilot-http.db"),
    "--profile",
    "cli_autopilot_http",
    "--port",
    "0",
    "--autopilot-interval-minutes",
    "0.001",
    "--embed-backfill-batch",
    "1",
  ],
  { cwd: process.cwd(), stdio: ["pipe", "pipe", "pipe"] },
);
let cliAutopilotHttpStdout = "";
let cliAutopilotHttpStderr = "";
cliAutopilotHttp.stdout.setEncoding("utf8");
cliAutopilotHttp.stderr.setEncoding("utf8");
cliAutopilotHttp.stdout.on("data", (chunk: string) => {
  cliAutopilotHttpStdout += chunk;
});
cliAutopilotHttp.stderr.on("data", (chunk: string) => {
  cliAutopilotHttpStderr += chunk;
});
const cliAutopilotHttpUrl = await Promise.race([
  new Promise<string>((resolve) => {
    cliAutopilotHttp.stdout.on("data", () => {
      const match = cliAutopilotHttpStdout.match(/"url": "(http:\/\/127\.0\.0\.1:\d+)"/u);
      if (match?.[1]) resolve(match[1]);
    });
  }),
  new Promise<never>((_, reject) => {
    cliAutopilotHttp.once("exit", (code, signal) => {
      reject(new Error(`gmos http serve --autopilot exited early: code=${code} signal=${signal} stderr=${cliAutopilotHttpStderr}`));
    });
  }),
  new Promise<never>((_, reject) =>
    setTimeout(() => reject(new Error(`gmos http serve --autopilot did not print url: ${cliAutopilotHttpStderr}`)), 5000),
  ),
]);
try {
  assert.match(cliAutopilotHttpStdout, /"enabled": true/);
  let autopilotStatus: Record<string, unknown> | undefined;
  for (let attempt = 0; attempt < 30; attempt += 1) {
    const status = await httpJson(`${cliAutopilotHttpUrl}/status`);
    autopilotStatus = status.body.autopilot as Record<string, unknown> | undefined;
    if (typeof autopilotStatus?.lastRunAt === "string") break;
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  assert.equal(autopilotStatus?.enabled, true);
  assert.equal(typeof autopilotStatus?.lastRunAt, "string");
} finally {
  cliAutopilotHttp.kill("SIGTERM");
  await Promise.race([
    new Promise((resolve) => cliAutopilotHttp.once("exit", resolve)),
    new Promise((resolve) => setTimeout(resolve, 5000)),
  ]);
}

const cliSnapshotAuthorityDbPath = path.join(tmp, "cli-snapshot-authority.db");
const cliSnapshotAuthorityStore = createSqliteMemoryStore({ path: cliSnapshotAuthorityDbPath });
await cliSnapshotAuthorityStore.initialize();
function legacyCliSnapshotPayload(
  name: string,
  createdAt: string,
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    schema: "gmos.profile_snapshot_point.v1",
    name,
    fileName: `${createdAt.replace(/[:.]/gu, "-")}-${name}.gmos-profile-bundle.json`,
    sha256: "0".repeat(64),
    bytes: 1,
    createdAt,
    bundleSchema: "gmos.profile_bundle.v2",
    mode: "full",
    ...overrides,
  };
}
await cliSnapshotAuthorityStore.recordEvidence({
  profileId: "cli_snapshot_authority",
  eventKey: "snapshot-unmarked-host-collision",
  sourceType: "snapshot",
  content: "Unmarked host snapshot collision.",
  sensitivity: "normal",
  eligibleForLongTermMemory: false,
  payload: { name: "forged-unmarked", id: "forged-unmarked-id" },
  createdAt: "2026-07-04T00:00:00.000Z",
});
const legacyCliSnapshotAt = "2026-07-04T00:00:10.000Z";
const legacyCliSnapshotEvidence = await cliSnapshotAuthorityStore.recordEvidence({
  profileId: "cli_snapshot_authority",
  eventKey: [
    "snapshot",
    "cli_snapshot_authority",
    legacyCliSnapshotAt,
    "legacy-snapshot",
  ].join(":"),
  sourceType: "snapshot",
  sourceUri: null,
  content: "Profile snapshot point",
  sensitivity: "normal",
  eligibleForLongTermMemory: false,
  payload: legacyCliSnapshotPayload("legacy-snapshot", legacyCliSnapshotAt),
  createdAt: legacyCliSnapshotAt,
});
for (const [name, eventKey, overrides] of [
  [
    "forged-event-key",
    "snapshot-forged-event-key",
    {},
  ],
  [
    "forged-file-name",
    [
      "snapshot",
      "cli_snapshot_authority",
      "2026-07-04T00:00:20.000Z",
      "forged-file-name",
    ].join(":"),
    { fileName: "wrong.gmos-profile-bundle.json" },
  ],
  [
    "forged-row-authority",
    [
      "snapshot",
      "cli_snapshot_authority",
      "2026-07-04T00:00:30.000Z",
      "forged-row-authority",
    ].join(":"),
    {
      id: "payload-forged-id",
      profileId: "payload-forged-profile",
      createdAt: "1900-01-01T00:00:00.000Z",
    },
  ],
] as const) {
  const createdAt = name === "forged-event-key"
    ? "2026-07-04T00:00:15.000Z"
    : name === "forged-file-name"
      ? "2026-07-04T00:00:20.000Z"
      : "2026-07-04T00:00:30.000Z";
  await cliSnapshotAuthorityStore.recordEvidence({
    profileId: "cli_snapshot_authority",
    eventKey,
    sourceType: "snapshot",
    sourceUri: null,
    content: "Profile snapshot point",
    sensitivity: "normal",
    eligibleForLongTermMemory: false,
    payload: legacyCliSnapshotPayload(name, createdAt, overrides),
    createdAt,
  });
}
const canonicalCliSnapshotEvidence = await cliSnapshotAuthorityStore.recordEvidence({
  profileId: "cli_snapshot_authority",
  eventKey: "snapshot-marked-authority",
  sourceType: "snapshot",
  content: "Marked profile snapshot point.",
  sensitivity: "normal",
  eligibleForLongTermMemory: false,
  payload: {
    _gmosSchema: GMOS_EVIDENCE_PAYLOAD_SCHEMAS.profileSnapshotPoint,
    name: "canonical-snapshot",
    id: "payload-forged-id",
    profileId: "payload-forged-profile",
    createdAt: "1900-01-01T00:00:00.000Z",
  },
  createdAt: "2026-07-04T00:01:00.000Z",
});
await cliSnapshotAuthorityStore.close();
const cliSnapshotAuthorityList = spawnSync(
  process.execPath,
  [
    "--import",
    "tsx",
    "src/cli/gmos.ts",
    "snapshot",
    "list",
    "--db",
    cliSnapshotAuthorityDbPath,
    "--profile",
    "cli_snapshot_authority",
  ],
  { cwd: process.cwd(), encoding: "utf8" },
);
assert.equal(cliSnapshotAuthorityList.status, 0, cliSnapshotAuthorityList.stderr);
const cliSnapshotAuthorityOutput = JSON.parse(cliSnapshotAuthorityList.stdout) as {
  snapshots: Array<Record<string, unknown>>;
};
assert.equal(cliSnapshotAuthorityOutput.snapshots.length, 2);
const listedCanonicalSnapshot = cliSnapshotAuthorityOutput.snapshots.find(
  (snapshot) => snapshot.name === "canonical-snapshot",
);
assert.equal(listedCanonicalSnapshot?.id, canonicalCliSnapshotEvidence.id);
assert.equal(listedCanonicalSnapshot?.profileId, "cli_snapshot_authority");
assert.equal(listedCanonicalSnapshot?.createdAt, "2026-07-04T00:01:00.000Z");
const listedLegacySnapshot = cliSnapshotAuthorityOutput.snapshots.find(
  (snapshot) => snapshot.name === "legacy-snapshot",
);
assert.equal(listedLegacySnapshot?.id, legacyCliSnapshotEvidence.id);
assert.equal(listedLegacySnapshot?.profileId, "cli_snapshot_authority");
assert.equal(listedLegacySnapshot?.createdAt, legacyCliSnapshotAt);
assert.equal(
  cliSnapshotAuthorityOutput.snapshots.some(
    (snapshot) => String(snapshot.name).startsWith("forged-"),
  ),
  false,
);

